//! Byte-for-byte vectors produced by the C++  path
//! (gate-spike/cxx-crosscheck). Regenerate by rebuilding that program
//! and .
#![allow(clippy::all)]

use tmwa_gate::proto::types::*;
use tmwa_gate::proto::*;

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02x}")).collect()
}

#[test]
fn position1_0x0078() {
    // C++: pos.x=999, pos.y=17, dir=DIR::W
    let mut p = P0078::default();
    p.pos = Position1 {
        x: 999,
        y: 17,
        dir: Dir(2),
    };
    let mut v = Vec::new();
    p.encode(&mut v);
    assert_eq!(hex(&v), EXPECT_0078);
}

#[test]
fn position2_0x0087() {
    // C++: pos2 = 13,1023 -> 998,1
    let mut p = P0087::default();
    p.pos2 = Position2 {
        x0: 13,
        y0: 1023,
        x1: 998,
        y1: 1,
    };
    let mut v = Vec::new();
    p.encode(&mut v);
    assert_eq!(hex(&v), EXPECT_0087);
}

#[test]
fn char_data_0x2afd() {
    let p = fixture_2afd();
    let mut v = Vec::new();
    p.encode(&mut v);
    assert_eq!(hex(&v), EXPECT_2AFD);
    // and decode it back losslessly
    let d = P2AFD::decode(&v).unwrap();
    let mut v2 = Vec::new();
    d.encode(&mut v2);
    assert_eq!(v2, v);
}

#[test]
#[ignore]
fn print_expected() {
    let p = fixture_2afd();
    let mut v = Vec::new();
    p.encode(&mut v);
    println!("{}", hex(&v));
}

